#!/usr/bin/env bash
set -euo pipefail
umask 077
readonly ROOT=/var/lib/orloom/c3-suite-jobs-20261013 PREFIX=orloom-c3-suite-jobs-20261013 LABEL=ORL-C3-SUITE-JOBS D=/usr/bin/docker SOCKET=unix:///var/run/docker.sock
readonly PG=postgres@sha256:b0f9560a2de083e2cc7382e75f808c7381a32852a7ec49117deedb300e552b24 NET=$PREFIX-net DB=$PREFIX-db DATA=$PREFIX-data SECRET=$PREFIX-secrets SEED=$PREFIX-seed
[[ ${EUID:-$(id -u)} -eq 0 && $# -eq 1 && $1 == /* && -f $1 && ! -L $1 && ! -e "$ROOT" && ! -L "$ROOT" ]] || { echo 'usage: root setup-disposable-postgres.sh /absolute/preflight.json' >&2; exit 64; }
observation=$(dirname "$1")/capacity-observation.json; [[ -f "$observation" && ! -L "$observation" ]] || { echo 'fresh capacity observation is required beside preflight' >&2; exit 66; }
[[ -d /var/lib/orloom && ! -L /var/lib/orloom && $(stat -c '%u' /var/lib/orloom) == 0 ]] || { echo 'trusted root unavailable' >&2; exit 69; }; mode=$(stat -c '%a' /var/lib/orloom); (( (8#$mode & 0022) == 0 )) || { echo 'trusted root is writable' >&2; exit 69; }
jq -e --arg label "$LABEL" --arg pg "$PG" 'type=="object" and (keys|sort)==["hostMutation","images","protectedContainer","providerCalls","runscRegistered"] and .hostMutation==false and .providerCalls==0 and .runscRegistered==true and (.protectedContainer|type=="string" and length>0) and .images.postgres==$pg' "$1" >/dev/null
protected=$(jq -r .protectedContainer "$1"); [[ $protected != *$'\n'* && $protected != *$'\r'* ]] || { echo 'invalid protected identity' >&2; exit 65; }
mem=$(awk '$1=="MemAvailable:" {printf "%.0f", $2*1024}' /proc/meminfo); disk=$(df -PB1 /var/lib | awk 'NR==2 {print $4}'); [[ $mem =~ ^[0-9]+$ && $disk =~ ^[0-9]+$ && $mem -ge 2147483648 && $disk -ge 4294967296 ]] || { echo 'host capacity is below admission floor' >&2; exit 75; }
config=$(mktemp -d /run/orloom-c3-suite-acceptance-docker.XXXXXX); chmod 0700 "$config"; trap 'rm -rf -- "$config"' EXIT HUP INT TERM
dc(){ env -i PATH=/usr/bin:/bin HOME=/root "$D" --config "$config" --host "$SOCKET" "$@"; }
pg_id=$(dc image inspect --format '{{.Id}}' "$PG"); [[ $pg_id =~ ^sha256:[a-f0-9]{64}$ && $(dc inspect --format '{{.Id}} {{.State.StartedAt}} {{.RestartCount}} {{.HostConfig.Runtime}} {{.State.Status}}' codex-universal) == "$protected" ]] || { echo 'protected host/image binding differs' >&2; exit 69; }
for name in "$DB" "$SEED"; do [[ -z $(dc ps -a --filter "name=^/${name}$" --format '{{.ID}}') ]] || { echo 'acceptance container name already exists' >&2; exit 73; }; done
[[ -z $(dc network ls --filter "name=^${NET}$" --format '{{.ID}}') && -z $(dc volume ls --filter "name=^${DATA}$" --format '{{.Name}}') && -z $(dc volume ls --filter "name=^${SECRET}$" --format '{{.Name}}') ]] || { echo 'acceptance resource name already exists' >&2; exit 73; }
install -d -m 0700 "$ROOT/incoming" "$ROOT/staging" "$ROOT/evidence" "$ROOT/artifacts"; install -m 0600 /dev/null "$ROOT/resources.tsv"; install -m 0400 "$1" "$ROOT/capacity-evidence.json"; install -m 0400 "$observation" "$ROOT/capacity-observation.json"
record(){ printf '%s\t%s\n' "$1" "$2" >> "$ROOT/resources.tsv"; }
netid=$(dc network create --internal --driver bridge --label "orloom.packet=$LABEL" "$NET"); record network "$netid"; dataid=$(dc volume create --label "orloom.packet=$LABEL" "$DATA"); record data-volume "$dataid"; secretid=$(dc volume create --label "orloom.packet=$LABEL" "$SECRET"); record secret-volume "$secretid"
seedid=$(dc create --pull=never --name "$SEED" --label "orloom.packet=$LABEL" --network none --read-only --cpus=.25 --memory=128m --memory-swap=128m --pids-limit=32 --mount "type=volume,src=$SECRET,dst=/run/secrets" --entrypoint=/bin/sh "$PG" -ec 'umask 077; chmod 0755 /run/secrets; od -An -N32 -tx1 /dev/urandom|tr -d " \n">/run/secrets/admin; od -An -N32 -tx1 /dev/urandom|tr -d " \n">/run/secrets/app; chown postgres:postgres /run/secrets/admin; chown 65532:65532 /run/secrets/app; chmod 0400 /run/secrets/admin /run/secrets/app; p=$(cat /run/secrets/app); printf "CREATE ROLE mission_app LOGIN PASSWORD '\''%s'\'';\nALTER DATABASE mission_proof OWNER TO mission_app;\nCREATE DATABASE mission_proof_aux OWNER mission_app;\n" "$p">/run/secrets/001-create.sql; unset p; chown postgres:postgres /run/secrets/001-create.sql; chmod 0400 /run/secrets/001-create.sql'); record seed "$seedid"
[[ $(dc inspect --format '{{.Id}}|{{index .Config.Labels "orloom.packet"}}|{{.Image}}' "$seedid") == "$seedid|$LABEL|$pg_id" ]] || exit 70; dc start --attach "$seedid" >/dev/null; [[ $(dc inspect --format '{{.State.Status}}|{{.State.ExitCode}}' "$seedid") == 'exited|0' ]]; dc rm "$seedid" >/dev/null; record seed-removed "$seedid"
dbid=$(dc run -d --pull=never --name "$DB" --label "orloom.packet=$LABEL" --network "$NET" --network-alias pg --restart=no --cpus=.50 --memory=512m --memory-swap=512m --pids-limit=64 --read-only --mount "type=volume,src=$DATA,dst=/var/lib/postgresql/data" --mount "type=volume,src=$SECRET,dst=/run/secrets,readonly" --mount "type=volume,src=$SECRET,dst=/docker-entrypoint-initdb.d,readonly" --tmpfs /tmp:rw,nosuid,nodev,size=64m,mode=1777 --tmpfs /var/run/postgresql:rw,nosuid,nodev,size=16m,uid=70,gid=70,mode=3775 --health-cmd='pg_isready -U mission_admin -d mission_proof' --health-interval=2s --health-timeout=2s --health-retries=30 -e POSTGRES_PASSWORD_FILE=/run/secrets/admin -e POSTGRES_USER=mission_admin -e POSTGRES_DB=mission_proof "$PG"); record database "$dbid"
[[ $(dc inspect --format '{{.Id}}|{{index .Config.Labels "orloom.packet"}}|{{.Image}}|{{json .HostConfig.PortBindings}}|{{json .HostConfig.Binds}}' "$dbid") == "$dbid|$LABEL|$pg_id|{}|null" ]] || exit 70
health=starting; for _ in $(seq 1 45); do health=$(dc inspect --format '{{.State.Health.Status}}' "$dbid"); [[ $health == healthy ]] && break; [[ $health != unhealthy ]] || exit 70; sleep 2; done; [[ $health == healthy ]] || exit 70
ip=$(dc inspect --format '{{range .NetworkSettings.Networks}}{{.IPAddress}}{{end}}' "$dbid"); [[ $ip =~ ^(10\.|172\.|192\.168\.) ]] || exit 70; password=$(dc exec "$DB" cat /run/secrets/app); [[ $password =~ ^[a-f0-9]{64}$ ]] || exit 70; printf 'postgres://mission_app:%s@%s:5432/mission_proof\n' "$password" "$ip" > "$ROOT/staging/database-url"; unset password; chmod 0400 "$ROOT/staging/database-url"
printf 'postgres_setup=READY database=%s network=%s capacity_sha256=%s\n' "$dbid" "$netid" "$(sha256sum "$ROOT/capacity-evidence.json" | cut -d' ' -f1)"
